/**
 * TypeScript File Writer Node for Node-RED
 * Allows creating and editing TypeScript files directly in Node-RED
 */

module.exports = function(RED) {
    "use strict";
    var fs = require('fs-extra');
    var path = require('path');
    
    function TypeScriptFileNode(n) {
        RED.nodes.createNode(this, n);
        var node = this;
        
        node.name = n.name;
        node.filePath = n.filePath;
        node.content = n.content;
        
        // Validate configuration
        if (!node.filePath) {
            node.error("File path is required");
            node.status({fill: "red", shape: "ring", text: "No file path"});
            return;
        }
        
        // Get userDir
        var userDir = RED.settings.userDir || process.env.NODE_RED_HOME || '.';
        var fullPath = path.resolve(userDir, node.filePath);
        var dirPath = path.dirname(fullPath);
        
        console.log('[TS-File] Node initialized:');
        console.log(`[TS-File] - Name: ${node.name || 'unnamed'}`);
        console.log(`[TS-File] - File path: ${node.filePath}`);
        console.log(`[TS-File] - Full path: ${fullPath}`);
        console.log(`[TS-File] - Content length: ${node.content ? node.content.length : 0} characters`);
        
        // Function to write file
        function writeFile() {
            try {
                // Ensure directory exists
                fs.ensureDirSync(dirPath);
                console.log(`[TS-File] Ensured directory exists: ${dirPath}`);
                
                // Write content to file
                fs.writeFileSync(fullPath, node.content, 'utf8');
                console.log(`[TS-File] ✅ Successfully wrote file: ${fullPath}`);
                console.log(`[TS-File] Content preview: ${node.content.substring(0, 100)}...`);
                
                node.status({fill: "green", shape: "dot", text: `Written: ${node.filePath}`});
                node.log(`TypeScript file written: ${node.filePath}`);
                
                return true;
            } catch (error) {
                console.error(`[TS-File] ❌ Error writing file: ${fullPath}`, error);
                node.error(`Failed to write file ${node.filePath}: ${error.message}`);
                node.status({fill: "red", shape: "ring", text: "Write error"});
                return false;
            }
        }
        
        // Write file on node creation (deploy)
        if (node.content) {
            // Small delay to ensure everything is set up
            setTimeout(() => {
                writeFile();
            }, 100);
        } else {
            node.status({fill: "yellow", shape: "ring", text: "No content"});
            node.warn("No content to write");
        }
        
        // Handle node close (cleanup if needed)
        node.on("close", function() {
            console.log(`[TS-File] Node closed: ${node.filePath}`);
            node.status({});
        });
        
        // This node has no inputs/outputs, it only writes files on deploy
        // The file writing happens during node initialization
    }
    
    RED.nodes.registerType("typescript-file", TypeScriptFileNode);
    
    // Add HTTP endpoint to refresh userDir types after file changes
    RED.httpAdmin.post("/function/typescript/refresh-userdir", function(req, res) {
        console.log('[TS-File] Received request to refresh userDir types');
        
        try {
            // This endpoint can be called by the editor to refresh types after file changes
            // For now, just return success - the typescript-function node handles the actual refresh
            res.json({ success: true, message: "UserDir types refresh requested" });
        } catch (error) {
            console.error('[TS-File] Error in refresh-userdir endpoint:', error);
            res.status(500).json({ success: false, error: error.message });
        }
    });
}; 